const LANG_IDX: Record<string, number> = { tr: 0, en: 1, ru: 2, ar: 3, fa: 4, fr: 5, de: 6, es: 7, pt: 8 };
export function countryName(code: string, lang: string): string {
  const row = COUNTRY_NAMES[code];
  if (!row) return code;
  return row[LANG_IDX[lang] ?? 0] || row[0];
}

