export function taxoName(value: string | undefined | null, lang: string): string {
  if (!value) return '';
  const row = TAXONOMY[value];
  if (!row) return value;
  return row[LANG_IDX[lang] ?? 0] || row[0];
}

// İlan içeriğini dile göre seç: details.i18n.<field>.<lang> varsa onu, yoksa ham alanı döndür.
export function lz(item: any, field: string, lang: string): string {
  const tr = item?.details?.i18n?.[field]?.[lang];
  return tr || item?.[field] || '';
}
