type I18nCtx = { lang: string; setLang: (c: string) => void; t: (k: string) => string; dir: string };
const Ctx = createContext<I18nCtx>({ lang: 'tr', setLang: () => {}, t: (k) => k, dir: 'ltr' });

function applyTheme(code: string) {
  const th = THEME_BY_LANG[code] || THEME_BY_LANG.tr;
  const r = document.documentElement.style;
  r.setProperty('--accent-a', th.a);
  r.setProperty('--accent-b', th.b);
  r.setProperty('--accent-solid', th.a);
  r.setProperty('--ui-font', th.ui);
  r.setProperty('--disp-font', th.disp);
}

export function I18nProvider({ children }: { children: React.ReactNode }) {
  const [lang, setLangState] = useState('tr');

  useEffect(() => {
    const saved = localStorage.getItem('lang') || 'tr';
    setLangState(saved);
  }, []);

  useEffect(() => {
    const l = LANGS.find((x) => x.code === lang) || LANGS[0];
    document.documentElement.setAttribute('lang', lang);
    document.documentElement.setAttribute('dir', l.dir);
    applyTheme(lang);
  }, [lang]);

  const setLang = useCallback((c: string) => {
    localStorage.setItem('lang', c);
    setLangState(c);
  }, []);

  const dir = (LANGS.find((x) => x.code === lang) || LANGS[0]).dir;
  // Eksik çeviri Türkçe yerine İngilizce'ye düşer (yabancı dilde Türkçe kelime kalmaz)
  const t = (k: string) => (I18N[lang] && I18N[lang][k]) || I18N.en[k] || I18N.tr[k] || k;

  return <Ctx.Provider value={{ lang, setLang, t, dir }}>{children}</Ctx.Provider>;
}

export const useI18n = () => useContext(Ctx);
